```javascript
function flatten(value) {
  if (!Array.isArray(value)) return [];

  const result = [];

  function recurse(arr) {
    for (const item of arr) {
      if (Array.isArray(item)) {
        recurse(item);
      } else {
        result.push(item);
      }
    }
  }

  recurse(value);
  return result;
}
