```javascript
function romanToInt(s) {
  const roman = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  let total = 0;

  for (let i = 0; i < s.length; i++) {
    const val = roman[s[i]];
    const nextVal = roman[s[i + 1]];

    if (nextVal !== undefined && val < nextVal) {
      total -= val;
    } else {
      total += val;
    }
  }

  return total;
}
```

```javascript
function gcd(a, b) {
  while (b !== 0) {
    const t = b;
    b = a % b;
    a = t;
  }
  return a;
}
